import java.util.*;

public class Main {
    String predictPartyVictory(String senateStr) {
        List<Character> senate = new ArrayList<>();
        for (char c : senateStr.toCharArray()) senate.add(c);
        while (senate.contains('R') && senate.contains('D')) {                          // a mutable list, simulating rounds by literally removing banned senators
            List<Character> result = new ArrayList<>();
            Character pendingBan = null;
            for (char c : senate) {
                if (pendingBan != null && pendingBan == c) {
                    pendingBan = null;                                                        // this senator was banned earlier in the same pass: skip it
                    continue;
                }
                pendingBan = (c == 'R') ? 'D' : 'R';                                          // this senator survives, and bans the NEXT opposing one encountered
                result.add(c);
            }
            senate = result;
        }
        return senate.contains('R') ? "Radiant" : "Dire";
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.predictPartyVictory("RD"));
        System.out.println(solution.predictPartyVictory("RDD"));
    }
}

