def predict_party_victory(senate):
    n = len(senate)
    radiant = deque(i for i, c in enumerate(senate) if c == 'R')           # indices of R senators, in original order
    dire = deque(i for i, c in enumerate(senate) if c == 'D')              # indices of D senators, in original order

    while radiant and dire:
        r_idx = radiant.popleft()
        d_idx = dire.popleft()
        if r_idx < d_idx:
            radiant.append(r_idx + n)                                      # R comes first: R bans D, then R re-queues for the NEXT round
        else:
            dire.append(d_idx + n)                                         # D comes first: D bans R, then D re-queues for the NEXT round

    return 'Radiant' if radiant else 'Dire'


