import java.util.*;

public class Main {
    String predictPartyVictory(String senate) {
        int n = senate.length();
        Deque<Integer> radiant = new ArrayDeque<>();                                     // indices of R senators, in original order
        Deque<Integer> dire = new ArrayDeque<>();                                        // indices of D senators, in original order
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') radiant.addLast(i);
            else dire.addLast(i);
        }

        while (!radiant.isEmpty() && !dire.isEmpty()) {
            int rIdx = radiant.pollFirst();
            int dIdx = dire.pollFirst();
            if (rIdx < dIdx) {
                radiant.addLast(rIdx + n);                                                    // R comes first: R bans D, then R re-queues for the NEXT round
            } else {
                dire.addLast(dIdx + n);                                                        // D comes first: D bans R, then D re-queues for the NEXT round
            }
        }

        return radiant.isEmpty() ? "Dire" : "Radiant";
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.predictPartyVictory("RD"));
        System.out.println(solution.predictPartyVictory("RDD"));
    }
}

