string predictPartyVictory(string senate) {
    int n = senate.size();
    queue<int> radiant, dire;                                                                 // indices of R/D senators, in original order
    for (int i = 0; i < n; i++) {
        if (senate[i] == 'R') radiant.push(i);
        else dire.push(i);
    }

    while (!radiant.empty() && !dire.empty()) {
        int rIdx = radiant.front(); radiant.pop();
        int dIdx = dire.front(); dire.pop();
        if (rIdx < dIdx) {
            radiant.push(rIdx + n);                                                               // R comes first: R bans D, then R re-queues for the NEXT round
        } else {
            dire.push(dIdx + n);                                                                   // D comes first: D bans R, then D re-queues for the NEXT round
        }
    }

    return radiant.empty() ? "Dire" : "Radiant";
}

int main() {
    cout << predictPartyVictory("RD") << endl;
    cout << predictPartyVictory("RDD") << endl;
    return 0;
